namespace DocSummary.Models;

public class SummarizeRequest
{
    public required string DocumentText { get; set; }
    public int MaxSentences { get; set; } = 3;
}

namespace DocSummary.Models;

public class SummarizeResponse
{
    public required string Summary { get; set; }
    public int OriginalLength { get; set; }
    public int SummaryLength { get; set; }
}

namespace DocSummary.Services;

public class DocumentSummarizationService
{
    /// <summary>
    /// Produces a concise summary by extracting the most important sentences.
    /// Uses a simple extractive approach based on sentence length and position.
    /// </summary>
    public string Summarize(string documentText, int maxSentences = 3)
    {
        if (string.IsNullOrWhiteSpace(documentText))
            return string.Empty;

        var sentences = SplitIntoSentences(documentText);

        if (sentences.Length <= maxSentences)
            return string.Join(" ", sentences);

        // Score sentences by position (earlier = more important) and length
        var scored = sentences
            .Select((sentence, index) => new
            {
                Sentence = sentence,
                Index = index,
                Score = ScoreSentence(sentence, index, sentences.Length)
            })
            .OrderByDescending(s => s.Score)
            .Take(maxSentences)
            .OrderBy(s => s.Index) // preserve original order
            .Select(s => s.Sentence);

        return string.Join(" ", scored);
    }

    private static string[] SplitIntoSentences(string text)
    {
        return text.Split(['.', '!', '?'], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                   .Where(s => s.Length > 0)
                   .Select(s => s + ".")
                   .ToArray();
    }

    private static double ScoreSentence(string sentence, int index, int totalSentences)
    {
        // Earlier sentences get higher positional score
        double positionScore = 1.0 - ((double)index / totalSentences);

        // Longer sentences (up to a point) are likely more informative
        double lengthScore = Math.Min(sentence.Length / 100.0, 1.0);

        return (positionScore * 0.6) + (lengthScore * 0.4);
    }
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummarizeController : ControllerBase
{
    private readonly DocumentSummarizationService _summarizationService;

    public SummarizeController(DocumentSummarizationService summarizationService)
    {
        _summarizationService = summarizationService;
    }

    [HttpPost]
    public IActionResult Summarize([FromBody] SummarizeRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.DocumentText))
            return BadRequest(new { error = "DocumentText is required and cannot be empty." });

        var summary = _summarizationService.Summarize(request.DocumentText, request.MaxSentences);

        var response = new SummarizeResponse
        {
            Summary = summary,
            OriginalLength = request.DocumentText.Length,
            SummaryLength = summary.Length
        };

        return Ok(response);
    }
}

